// 我仿照后端@Kai Yang写的版本文件上传+升级的js，写出的音频文件上传的js（音频文件无升级）

/* eslint-disable */
import proto from '@/utils/sdkapi_pb.js'
import { useXhumanoidFrame } from '@/hooks/useXhumanoidFrame'
const { wrapWithXhumanoidFrame } = useXhumanoidFrame()

class SpeechUpload {
  constructor() {
    this.request_map = new Map()
  }

  setSocketUrl(url) {
    this.wsUrl = url
  }

  init(files, type, event) {
    this.files = files
    this.type = type
    this.event = event
    this.total = files.size
    this.step = 1024 * 1024 * 1
    this.loaded = 0
    this.reader = new FileReader()
    this.abort = this.reader.abort
    this.bindEvent()
    this.readPartFile(this.loaded)
  }

  // 切片读取
  readPartFile(start) {
    if (!this.files || !this.files.slice) {
      console.error('read part file error', this.files)
      return
    }
    const file = this.files.slice(start, this.loaded + this.step)
    this.reader.readAsArrayBuffer(file)
  }

  // 绑定各事件
  bindEvent() {
    const self = this
    this.reader.onloadstart = function (e) {
      self.event.loadStart && self.event.loadStart.call(this, e)
    }
    this.reader.onprogress = function (e) {
      self.event.progress && self.event.progress.call(this, e)
    }
    this.reader.onload = function (e) {
      self.loaded += e.loaded
      self.event.load && self.event.load.call(this, e, self.loaded, self.total)
    }
    this.reader.onloadend = function (e) {
      self.event.loadend && self.event.loadend.call(this, e)
    }
    this.reader.onabort = function (e) {
      self.event.abort && self.event.abort.call(this, e)
    }
  }

  openSocket(obj, e) {
    let socket = null
    if (typeof WebSocket === 'undefined') {
      console.error('当前浏览器不支持WebSocket')
      return
    }
    const socketUrl = this.wsUrl
    if (socket != null) {
      socket.close()
      socket = null
    }
    socket = new WebSocket(socketUrl, 'upgrade')

    socket.onopen = () => {
      if (e.onopen) e.onopen(socket, obj)
    }
    socket.onmessage = (msg) => {
      this.onWebSocketMessage(socket, msg)
    }
    socket.onclose = () => {
      // console.log('websocket closed')
    }
    socket.onerror = () => {
      console.error('websocket error')
    }
  }

  // 读取切片→组包→发送
  readFile(socket, file, obj) {
    this.package_block_index = 0
    this.request_map = new Map()
    this.request_uid = Date.now() + '' // 用于 taskid

    this.init(file, 'readAsArrayBuffer', {
      load: (e, loaded, total) => {
        const request = new proto.Request()
        request.setCommand(proto.Command.CMD_RUN_UPLOAD_FILE)

        const user_data = this.request_uid + '_' + loaded
        const header = new proto.Header()
        header.setUserdata(user_data)
        request.setHeader(header)

        //param_data
        let p = request.addParamData()
        p.setKey('cmdtype')
        p.setVal('UPLOAD_FILE_SPEECH')

        p = request.addParamData()
        p.setKey('speech_id') // group.id
        p.setVal(obj.speech_id + '')

        p = request.addParamData()
        p.setKey('package_name')
        p.setVal(obj.package_name + '')

        p = request.addParamData()
        p.setKey('package_loaded')
        p.setVal(loaded + '')

        p = request.addParamData()
        p.setKey('package_total')
        p.setVal(total + '')

        p = request.addParamData()
        p.setKey('package_block_index')
        p.setVal(this.package_block_index + '')

        p = request.addParamData()
        p.setKey('package_block_data')
        p.setData(new Uint8Array(e.target.result))

        p = request.addParamData()
        p.setKey('taskid')
        p.setVal(this.request_uid)

        obj.cmdtype = 'UPLOAD_FILE_SPEECH'
        obj.percent = Math.round((loaded / total) * 100)
        this.request_map.set(user_data, obj)

        const d = request.serializeBinary()
        socket.send(wrapWithXhumanoidFrame(d))

        // this.package_block_index++
      }
    })
  }

  onWebSocketMessage(socket, msg) {
    const reader = new FileReader()
    reader.onload = () => {
      const d = proto.Response.deserializeBinary(reader.result)
      const j = proto.Response.toObject(null, d)

      if (j.command !== proto.Command.CMD_RUN_UPLOAD_FILE) return

      const mapKey = j.header?.userdata
      const obj = mapKey ? this.request_map.get(mapKey) : null
      if (!obj) return

      if (j.errorCode === proto.ErrorCode.ERROR_CODE_SUCCESS) {
        if (this.loaded < this.total) {
          if (obj.onEventUploadPercent) {
            obj.onEventUploadPercent(obj, { percent: obj.percent })
          }
          this.readPartFile(this.loaded)
        } else {
          if (obj.onEventUploadFinished) {
            obj.onEventUploadFinished(obj, { percent: 100 })
          }
        }
      } else {
        if (obj.onEventErrorMessage) obj.onEventErrorMessage(obj, j)
      }
    }
    reader.readAsArrayBuffer(msg.data)
  }

  startUpload(file, obj) {
    obj.task = 'SPEECH_UPLOAD_FILE'
    this.openSocket(obj, {
      onopen: (socket, obj) => {
        this.readFile(socket, file, obj || {})
      }
    })
  }
}

export default SpeechUpload
