<template>
  <div class="flex-direction-column">
    <!-- 每个声卡设备卡片 -->
    <div
      class="g-page-container-with-header"
      v-for="audioitem in sortedAudioData"
      :key="audioitem.devid"
    >
      <div class="container-header flex-space-between">
        <span class="title">{{ audioitem.devdesp }}</span>
      </div>
      <div class="container-content">
        <div class="g-kv-pair" v-for="(label, key) in displayLabels" :key="key">
          <div class="label">{{ label }}</div>
          <div
            class="value"
            :style="key === 'status' ? getStatusTextStyle(audioitem[key]) : {}"
          >
            {{ getDisplayValue(audioitem, key) }}
          </div>
        </div>
      </div>
    </div>

    <!-- 音频文件表格：每个目录一张表 -->
    <div
      class="g-page-container-with-header"
      v-for="group in speechData"
      :key="group.id"
    >
      <div class="container-header flex-space-between">
        <span class="title">{{ group.path }}</span>
        <div class="btns" style="display: flex; gap: 8px">
          <div class="g-button" @click="openUploadDialog(group)">上传</div>
          <div class="g-button" @click="handleStopPlay">停止播放</div>
        </div>
      </div>
      <div class="container-content">
        <el-table :data="getSpeechFileRows(group)" style="width: 100%">
          <el-table-column prop="type" label="类型" width="100" />
          <el-table-column prop="desc" label="描述" width="150" />
          <el-table-column prop="path" label="目录" width="250" />
          <el-table-column prop="address" label="地址" width="140" />
          <el-table-column prop="name" label="文件名" />
          <el-table-column label="操作" width="160">
            <template #default="{ row }">
              <el-button size="small" @click="handlePlay(row.id)"
                >播放</el-button
              >
              <el-button
                v-if="row.deletable"
                size="small"
                type="danger"
                @click="handleDelete(row.id)"
              >
                删除
              </el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
    </div>
  </div>

  <!-- 音频上传弹窗 -->
  <el-dialog
    v-model="uploadDialogVisible"
    title="上传音频文件"
    width="40%"
    :close-on-click-modal="false"
  >
    <div class="right g-page-container">
      <div class="upload">
        <div
          class="g-button upload-btn"
          :class="{ disabled: isUploading }"
          @click="triggerSpeechUploadInput"
        >
          上传文件
          <img src="@/assets/img/upload/LogoLittle.png" class="upload-icon" />
        </div>

        <div
          class="upload-area"
          :class="{ disabled: isUploading }"
          @click="triggerSpeechUploadInput"
          @dragover.prevent
          @drop.prevent="handleSpeechDrop"
        >
          <img src="@/assets/img/upload/LogoBig.png" class="upload-big-icon" />
          <div class="el-upload__text">
            拖拽或点击上传 .mp3/.wav 至目录<br />
            {{ currentSpeechGroup?.path }}
          </div>

          <input
            type="file"
            ref="speechFileInput"
            accept=".mp3,.wav"
            style="display: none"
            @change="handleSpeechSelect"
          />
        </div>
      </div>

      <div class="g-table">
        <!-- 表头 -->
        <div class="cell flex-space-between header">
          <div class="name bg filename">文件名</div>
          <div class="name bg filesize">大小</div>
          <div class="name bg filestatus">状态</div>
          <div class="name bg fileaction">操作</div>
        </div>
        <!-- 文件行 -->
        <div
          class="cell flex-space-between file-row"
          v-for="(file, idx) in speechUploadedFiles"
          :key="idx"
        >
          <div class="name filename">{{ file.name }}</div>
          <div class="name filesize">{{ file.size }}</div>
          <div class="name filestatus status">
            <img :src="getSpeechStatusIcon(file.status)" class="status-icon" />
            {{ getSpeechStatusText(file.status, file.percent) }}
          </div>
          <div class="name fileaction action">
            <div
              class="g-button"
              @click="startSpeechUpload(file)"
              v-if="file.status === 'pending'"
            >
              开始上传
            </div>
          </div>
        </div>
      </div>
    </div>
  </el-dialog>
</template>

<script setup>
import { computed, watch, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { useWslStore } from '@/store/modules/ws.js'
import { useSortData } from '@/hooks/useSortData'
import { useDataMerge } from '@/hooks/useDataMerge'
import { useCommand } from '@/hooks/useCommand'
import { useStatus } from '@/hooks/useStatus'
import { useTimeFormat } from '@/hooks/useTimeFormat'
import { ElMessage } from 'element-plus'

import SpeechUpload from '@/utils/speech_upload.js'

const store = useWslStore()
const { received } = storeToRefs(store)
const { sendAudioCommand } = useCommand(store)
const { getStatusTextStyle } = useStatus()
const { formatTimestamp } = useTimeFormat()

const displayLabels = {
  devid: '设备ID',
  devname: '设备名称',
  devtype: '设备类型',
  devdesp: '设备描述',
  status: '状态',
  timestamp: '时间',
  address: '设备IP地址'
}

const getSpeechFileRows = (group) => {
  const fileList = group.speechFileList || []
  return fileList.map((file) => ({
    ...file,
    type: group.type,
    desc: group.desc,
    path: group.path,
    address: group.address
  }))
}

const audioData = useDataMerge(
  computed(() => {
    const data = received.value?.statusData?.audioDataList
    if (!data || data.length === 0) {
      // 返回两条 mock 数据
      return [
        {
          devid: -1,
          devdesp: '暂无设备',
          status: 'warn'
        }
      ]
    }
    return data
  }),
  { idField: 'devid' }
).mergedData

const sortedAudioData = useSortData(audioData, {
  key: 'devid',
  type: 'number',
  order: 'asc'
}).sortedData

const speechData = useDataMerge(
  computed(() => {
    const data = received.value?.statusData?.speechDataList
    if (!data || data.length === 0) {
      return [
        {
          id: 'empty-1',
          type: '暂无1',
          address: '暂无1',
          path: '/暂无1',
          desc: '暂无音频1',
          speechFileList: [
            {
              id: 'empty-1-1',
              name: '暂无文件1',
              deletable: false
            },
            {
              id: 'empty-1-2',
              name: '暂无文件2',
              deletable: false
            }
          ]
        },
        {
          id: 'empty-2',
          type: '暂无2',
          address: '暂无2',
          path: '/暂无2',
          desc: '暂无音频2',
          speechFileList: [
            {
              id: 'empty-2-1',
              name: '暂无文件1',
              deletable: false
            },
            {
              id: 'empty-2-2',
              name: '暂无文件2',
              deletable: false
            }
          ]
        }
      ]
    }
    return data
  }),
  { idField: 'id' }
).mergedData

const getDisplayValue = (item, key) => {
  let value = item[key]
  if (key === 'timestamp' && value) {
    value = formatTimestamp(value)
  }
  return value === null || value === undefined || value === '' ? '-' : value
}

const handlePlay = (id) => {
  sendAudioCommand('PLAY_AUDIO_FILE', id)
}

const handleDelete = (id) => {
  sendAudioCommand('DELETE_AUDIO_FILE', id)
}

const handleStopPlay = () => {
  sendAudioCommand('STOP_PLAY_AUDIO')
}

watch(
  () => received.value,
  (resp) => {
    if (!resp) return
    const cmd = resp.command
    if (cmd !== 'CMD_RUN_DEVICE_CONTROL' && cmd !== 49) return
    const code = resp.errorCode
    const isSuccess = code === 0 || code === 'ERROR_CODE_SUCCESS'

    if (isSuccess) {
      ElMessage.success('操作成功')
    } else {
      ElMessage({
        type: 'error',
        message: resp.errorMessage || '操作失败',
        duration: 0,
        showClose: true
      })
    }
  },
  { deep: true }
)

//上传音频部分
const uploadDialogVisible = ref(false)
const currentSpeechGroup = ref(null)
const speechFileInput = ref(null)
const speechUploadedFiles = ref([])

const socketHostUrl =
  process.env.NODE_ENV === 'development'
    ? process.env.VUE_APP_WS_URL.replace('/status', '')
    : `ws://${window.location.hostname}:7123`

const isUploading = computed(() => {
  const file = speechUploadedFiles.value[0]
  return file?.status === 'uploading'
})

const openUploadDialog = (group) => {
  currentSpeechGroup.value = group
  uploadDialogVisible.value = true
  speechUploadedFiles.value = []
}

const triggerSpeechUploadInput = () => {
  speechFileInput.value?.click()
}

const handleSpeechSelect = (e) => {
  const f = e.target.files[0]
  handleSpeechFile(f)
}

const handleSpeechDrop = (e) => {
  const f = e.dataTransfer.files[0]
  handleSpeechFile(f)
}

const handleSpeechFile = (file) => {
  if (!file || (!file.name.endsWith('.mp3') && !file.name.endsWith('.wav'))) {
    ElMessage.error('仅支持 .mp3 / .wav 文件')
    return
  }

  speechUploadedFiles.value = [
    {
      name: file.name,
      raw: file,
      size: `${(file.size / 1024 / 1024).toFixed(2)}MB`,
      status: 'pending',
      percent: 0
    }
  ]
}

const getSpeechStatusIcon = (status) => {
  return (
    {
      pending: require('@/assets/img/upload/uploadPend.png'),
      uploading: require('@/assets/img/upload/uploading.png'),
      success: require('@/assets/img/upload/uploadSuccess.png'),
      error: require('@/assets/img/upload/uploadError.png')
    }[status] || ''
  )
}

const getSpeechStatusText = (status, percent) => {
  if (status === 'uploading') return `上传中 ${percent || 0}%`
  return (
    {
      pending: '待上传',
      success: '上传成功',
      error: '上传失败'
    }[status] || ''
  )
}

const startSpeechUpload = (file) => {
  file.status = 'uploading'
  const uploader = new SpeechUpload()
  uploader.setSocketUrl(`${socketHostUrl}/audio/upgrade`)

  uploader.startUpload(file.raw, {
    speech_id: currentSpeechGroup.value.id, //传当前目录的id
    package_name: file.name,
    onEventUploadPercent: (obj, data) => {
      file.percent = data.percent
    },
    onEventUploadFinished: () => {
      file.status = 'success'
      ElMessage.success('上传成功')
    },
    onEventErrorMessage: (obj, resp) => {
      file.status = 'error'
      // ElMessage.error(resp?.errorMessage || '上传失败')
      ElMessage({
        type: 'error',
        message: resp?.errorMessage || '上传失败',
        duration: 0,
        showClose: true
      })
    }
  })
}
</script>

